#include <iostream>
#include <vector>
#include <functional>
using namespace std;

class Stream {
    vector<int> data;
public:
    Stream(const vector<int>& v) : data(v) {}

    Stream map(function<int(int)> fn) const {
        vector<int> result;
        for (int x : data) result.push_back(fn(x));
        return Stream(result);
    }

    Stream filter(function<bool(int)> pred) const {
        vector<int> result;
        for (int x : data) if (pred(x)) result.push_back(x);
        return Stream(result);
    }

    void collect() const {
        for (int x : data) cout << x << " ";
        cout << endl;
    }
};

int main() {
    Stream({1,2,3,4,5})
        .map([](int x){ return x * 2; })
        .filter([](int x){ return x > 5; })
        .collect();
    return 0;
}
